import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { type Browser, expect, type Page, test } from "@playwright/test";

export const USERS = ["marta.ops", "daniel.sales", "priya.sales", "sanna.inventory", "tomas.admin", "rafael.integration", "helena.compliance"] as const;
export const STATE_DIR = fileURLToPath(new URL("../../.auth/", import.meta.url));
export const stateFile = (username: string) => `${STATE_DIR}${username}.json`;

// Demo credentials are generated by `make demo-users` into a git-ignored, mode-0600 file; never hard-coded.
const CREDENTIALS = fileURLToPath(new URL(`../../../deploy/secrets/${process.env.LBF_NS ? `${process.env.LBF_NS}-` : "demo-"}credentials.txt`, import.meta.url));

export function password(username: string): string {
  const line = readFileSync(CREDENTIALS, "utf-8").split("\n").find((l) => l.startsWith(username + "\t"));
  if (!line) throw new Error(`no demo credentials for ${username}; run make demo-users`);
  return line.split("\t")[1]!;
}

/** A page signed in as ``username`` (session from the global setup; no new login). */
export async function as(browser: Browser, username: (typeof USERS)[number]): Promise<Page> {
  const context = await browser.newContext({ storageState: stateFile(username) });
  return context.newPage();
}

export async function createDraft(page: Page, account = "00417", sku = "BW-1001", qty = "2"): Promise<string> {
  await page.goto("/operations/new");
  await page.getByLabel("Account number").fill(account);
  await page.getByLabel("Group SKU").fill(sku);
  await page.getByLabel("Quantity").fill(qty);
  await page.getByRole("button", { name: "Create draft" }).click();
  // drafting reads HALDEN live (customer + catalogue); its frozen rate limit can delay the response by seconds
  await expect(page).toHaveURL(/\/operations\/[0-9a-f-]{36}$/, { timeout: 30_000 });
  return page.url().split("/").pop()!;
}

// ---------------------------------------------------------------------------------------------------------------
// Test-profile control (acceptance/e2e_ctl.py): reset, faults, restart/kill at pause points, independent oracles.
// These act *outside* the application, as a tester would; the console itself is only driven through the browser.

const BACKEND_DIR = fileURLToPath(new URL("../../../backend/", import.meta.url));

export function ctl(...args: string[]): Record<string, unknown> {
  const out = execFileSync("uv", ["run", "--frozen", "python", "../acceptance/e2e_ctl.py", ...args], {
    cwd: BACKEND_DIR, env: { ...process.env, PYTHONPATH: ".." }, encoding: "utf-8", timeout: 240_000,
  });
  return JSON.parse(out.trim().split("\n").pop()!) as Record<string, unknown>;
}

export type Oracle = { wire_e8: number; halden_orders: number; halden_order_nos: string[]; skarvik_claims: number; skarvik_orders: number };
export const oracle = (correlation: string) => ctl("counts", correlation) as unknown as Oracle;

/** Draft and submit as daniel.sales; returns [operation id, correlation value]. */
export async function readyOrder(page: Page, backend: "halden" | "skarvik", account: string, sku = "BW-1001", qty = "10"): Promise<[string, string]> {
  await page.goto("/operations/new");
  await page.getByLabel("Backend").selectOption(backend);
  await page.getByLabel("Account number").fill(account);
  await page.getByLabel("Group SKU").fill(sku);
  await page.getByLabel("Quantity").fill(qty);
  await page.getByRole("button", { name: "Create draft" }).click();
  await expect(page).toHaveURL(/\/operations\/[0-9a-f-]{36}$/, { timeout: 30_000 });
  const id = page.url().split("/").pop()!;
  await page.getByRole("button", { name: "Submit for approval" }).click();
  await expect(heading(page)).toContainText("Awaiting approval", { timeout: 30_000 });
  return [id, await correlation(page)];
}

export const heading = (page: Page) => page.getByRole("heading", { level: 1 });

export async function correlation(page: Page): Promise<string> {
  return (await heading(page).locator(".mono").first().innerText()).trim();
}

export async function approve(page: Page, id: string): Promise<void> {
  await page.goto(`/operations/${id}`);
  await page.getByRole("button", { name: "Approve…" }).click();
  await page.getByRole("button", { name: "Approve", exact: true }).click();
}

/** Wait for the operation page heading to show ``text`` (the page polls; a reload covers an app restart). */
export async function waitStatus(page: Page, id: string, text: string | RegExp, timeoutMs = 90_000): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    try {
      await page.goto(`/operations/${id}`);
      await expect(heading(page)).toContainText(text, { timeout: 5_000 });
      return;
    } catch (e) {
      if (Date.now() > deadline) throw e;
      await page.waitForTimeout(1_000);
    }
  }
}

/** The state transitions recorded in the operation's audit timeline, e.g. "SUBMITTING → UNKNOWN". */
export async function transitions(page: Page): Promise<string> {
  // the timeline shows the latest 6 events by default; expand it before reading every transition
  const more = page.getByRole("button", { name: /^Show \d+ earlier events$/ });
  if (await more.count()) await more.click();
  return page.locator("ol").last().innerText();
}

export async function evidenceShot(page: Page, name: string): Promise<void> {
  const dir = process.env.LBF_E2E_EVIDENCE;
  if (dir) await page.screenshot({ path: `${dir}/${name}.png`, fullPage: true });
}

// ---------------------------------------------------------------------------------------------------------------
// Operational commands observed end to end (T-G2-01): BUTTON CLICKED → REQUEST DISPATCHED → HTTP RESPONSE
// OBSERVED → AUTHORIZATION RESULT OBSERVED → PERSISTED STATE VERIFIED (server read model) → UI STATE VERIFIED.

type Json = Record<string, unknown>;
export type Detail = {
  operation: { state: string; last_evidence: string | null };
  authorizations: { id: string; kind: string; state: string }[];
  transmissions: { kind: string; authorization_id: string }[];
  timeline: { seq: number; event_type: string; actor_username: string | null; correlation: Json; payload: Json;
    state: { from: string; to: string } | null }[];
};

/** The server's persisted view of one operation (the same authenticated read API the console uses). */
export async function detail(page: Page, id: string): Promise<Detail> {
  const r = await page.request.get(`/api/v1/operations/${id}`);
  expect(r.status()).toBe(200);
  return (await r.json()) as Detail;
}

export type CommandResult = { status: number; body: Json; refusedFirst: boolean };

/** Click ``submit`` and observe that command's own HTTP exchange (never inferred from what the page shows later). */
async function observe(page: Page, id: string, endpoint: string, submit: () => Promise<void>): Promise<{ status: number; body: Json }> {
  const path = `/api/v1/operations/${id}/${endpoint}`;
  const ours = (url: string, method: string) => method === "POST" && new URL(url).pathname === path;
  const dispatched = page.waitForRequest((r) => ours(r.url(), r.method()));
  const answered = page.waitForResponse((r) => ours(r.url(), r.request().method()));
  await submit();
  await dispatched;
  const response = await answered;
  return { status: response.status(), body: (await response.json()) as Json };
}

/**
 * An operator command issued through the console with its outcome observed. D-G2-02 contract (accepted by design):
 * a command that reaches the server while a scheduled re-check holds the order in RECONCILING is refused with
 * 409 CONFLICT_STATE and changes nothing. That refusal is asserted in full (status, code, detail, no authorization,
 * no handoff, no operator event, the refusal shown on the page, the persisted state back in UNKNOWN); the operator
 * then issues the command once more as a new, separately observed request. Any other status is returned as is.
 */
export async function operatorCommand(page: Page, id: string, endpoint: string, openDialog: string, submit: string): Promise<CommandResult> {
  const issue = async () => {
    await page.getByRole("button", { name: openDialog }).click();
    return observe(page, id, endpoint, () => page.getByRole("button", { name: submit, exact: true }).click());
  };
  const before = await detail(page, id);
  const first = await issue();
  if (first.status !== 409) return { ...first, refusedFirst: false };
  expect(first.body.code).toBe("CONFLICT_STATE");
  expect(first.body.detail).toBe("not permitted from state RECONCILING");
  await expect(page.getByRole("alert").filter({ hasText: "CONFLICT_STATE" })).toBeVisible();
  const refused = await detail(page, id);
  expect(refused.authorizations).toEqual(before.authorizations.map((a) => expect.objectContaining({ id: a.id, kind: a.kind })));
  expect(refused.transmissions).toHaveLength(before.transmissions.length);
  const userEvents = (d: Detail) => d.timeline.filter((e) => e.actor_username != null);
  expect(userEvents(refused)).toHaveLength(userEvents(before).length); // no AUTHORIZATION_CREATED / WITHDRAW_RESULT
  await expect.poll(async () => (await detail(page, id)).operation.state, { timeout: 10_000 }).toBe("UNKNOWN");
  test.info().annotations.push({ type: "D-G2-02 refusal observed",
    description: `${endpoint}: 409 CONFLICT_STATE during RECONCILING; nothing changed; re-issued once` });
  await page.reload();
  return { ...(await issue()), refusedFirst: true };
}
